namespace Puck.SdfVm;

/// <summary>The mesh irradiance probe record shared by the CPU tracer and views shader, generated by <see cref="SdfIsaHlsl"/>.
/// It holds a key, six sky halves, eighteen radiance halves, light visibility bits, the relocated origin, and an octahedral map of first-hit surface support.</summary>
public static class SdfMeshIrradianceProbe {
    /// <summary>The octahedral depth map's width and height, without duplicated border texels.</summary>
    public const int DepthSize = 12;
    /// <summary>The first surface word: FP16 ray distance and two signed octahedral normal bytes.
    /// A negative distance means a miss to that reach.</summary>
    public const int DepthWord = 19;
    /// <summary>The packed surface words followed by one FP16 normal-gradient curvature per texel.</summary>
    public const int DepthWords = (((3 * DepthSize) * DepthSize) / 2);
    /// <summary>The signed octahedral normal byte's scale; axis normals remain exact.</summary>
    public const float DepthNormalScale = 127f;
    /// <summary>The surface gap over which an angular tap closes, in metres, smaller than normal bias.</summary>
    public const float DepthSurfaceFade = 0.02f;
    /// <summary>The symmetric point/normal residual below which angular taps belong to one smooth surface patch.</summary>
    public const float DepthSurfaceJoinGap = (2f * DepthSurfaceFade);
    /// <summary>The volume's nested levels, finest first; each level's slots follow the finer level's in the table.</summary>
    public const int Levels = Puck.Shaders.SdfWorldPackage.MeshIrradianceLevelCount;
    /// <summary>The words one probe takes in the volume table.</summary>
    public const int ProbeWords = (DepthWord + DepthWords);
    /// <summary>Two words of FP16 offset XYZ and back-face share. Every directional read uses this relocated origin.</summary>
    public const int OffsetWord = 17;
    /// <summary>The least distance in metres between a probe and any surface.</summary>
    public const float Clearance = 0.1f;
    /// <summary>The share of a probe's rays meeting back faces past which the probe lies inside geometry.</summary>
    public const float InsideShare = 0.25f;
    /// <summary>The exposure meter's sky visibility over the mean open share of a probe's six axes: on open ground the up
    /// axis sees the whole sky, the four sideways axes half of it and the down axis none, a mean of one half.</summary>
    public const float OpenGroundShare = 2f;
    /// <summary>The distance in metres within which the meter's camera stands at a probe and casts no visibility ray to
    /// it.</summary>
    public const float MeterCoincident = 1.0e-3f;
    /// <summary>The distance in metres a shadow ray toward a point light ends before the light, so a fixture sunk a little
    /// into its housing is not blocked by it.</summary>
    public const float LightBias = 0.02f;
    /// <summary>The distance in metres a changed draw's box grows by, and a ray's recorded hit extends by at least, so a
    /// hit on the draw's own face always meets its box.</summary>
    public const float BoxMargin = 1.0e-3f;
    /// <summary>The share of a recorded hit's distance the hit extends by where that exceeds <see cref="BoxMargin"/>.</summary>
    public const float BoxMarginShare = 1.0e-4f;
    /// <summary>The first word of the traced light visibility bits, one bit per lights-table record.</summary>
    public const int LightsWord = 13;
    /// <summary>The number of light visibility words.</summary>
    public const int LightWords = 4;
    /// <summary>The flag a written probe carries.</summary>
    public const uint WrittenFlag = (1u << 30);
    /// <summary>The flag of a probe no candidate could move into the open.</summary>
    public const uint InvalidFlag = (1u << 31);
    /// <summary>The receiver's normal bias in metres, smaller than the thinnest wall, independent of probe spacing.</summary>
    public const float NormalBias = 0.05f;
    /// <summary>A probe's surface map reach in cell diagonals: with <see cref="NormalBias"/> added, the farthest
    /// receiver in metres a probe measured, its surface map past that a miss. A level's probes answer receivers this far
    /// past its window's boundary probes before a coarser level does.</summary>
    public const float SurfaceReach = 1.5f;
    /// <summary>The share of a level's surface reach past its window's boundary probes over which that level keeps its
    /// whole share of a receiver's answer; from there to the reach the share eases to none, and the next stage takes the
    /// rest.</summary>
    public const float SurfaceReachFadeStart = 0.5f;
    /// <summary>The facing weight a finest-level probe behind the receiver's plane keeps: small beside a probe in front, so
    /// it barely shifts a receiver that front probes light, and the whole answer for a receiver no front probe can see,
    /// such as a downward rim at the ground whose front probes the ground hides, which would otherwise draw black. A coarser
    /// level's probe behind the plane keeps none: its depth test cannot resolve the receiver's own wall.</summary>
    public const float BehindShare = 0.05f;
    /// <summary>The share of a receiver's angular taps blocked by solids at which their block starts closing: a minority
    /// tap cannot extend a finite block over the footprint, so a tap half on a railing does not shadow the floor beyond it,
    /// and a coarse probe's metres-wide tap on a hill's near bulge does not shadow the hill's far slope it sees.</summary>
    public const float DepthCoverageStart = 0.5f;
    /// <summary>Scales the solids' closing ramp to complete at three-quarter coverage.</summary>
    public const float DepthCoverageScale = 4f;
    /// <summary>The share of a receiver's angular taps blocked by sheets at which their block starts closing: none, since
    /// a measured hit on a sheet before the receiver is a slab or a wall with another space beyond it.</summary>
    public const float DepthSheetCoverageStart = 0f;
    /// <summary>Scales the sheets' closing ramp to complete at an eighth of the footprint blocked.</summary>
    public const float DepthSheetCoverageScale = 8f;
    /// <summary>The thickness, in metres, below which a surface a probe's ray hit is a sheet (a slab, a wall, a panel)
    /// rather than the near side of a solid: the solid behind the hit holds no ball of this diameter touching it, which
    /// the trace measures as a surface within 0.45 of it from the point half of it inside. A sheet's surface word sets
    /// the low bit of its texel's curvature half.</summary>
    public const float DepthSheetThickness = 2f;
}
